package net.minecraft.client.gui.components;import net.minecraft.network.chat.Component;public class Button{public interface OnPress{void onPress(Button b);}public Component text;public OnPress cb;public int x,y,w,h;public static Builder builder(Component text,OnPress cb){return new Builder(text,cb);}public static class Builder{Button b=new Button();public Builder(Component t,OnPress c){b.text=t;b.cb=c;}public Builder bounds(int x,int y,int w,int h){b.x=x;b.y=y;b.w=w;b.h=h;return this;}public Button build(){return b;}}}
